            + `<div class="igs-vy-iv-tag"><i class="igs-vy-rec-dot"></i>INTERVIEW${item.who ? `<span>${esc(item.who)}</span>` : ''}</div>`;
        const person = el(env.doc, 'igs-vy-iv-person');
