const FAN_MEDAL_SUFFIXES = f(['团子', '家', '宝', '崽', '粉', '卫', '党', '军', '的狗', '后援会', '观察员', '小可爱']);
function fanMedalNameFor(streamer, custom) {
    const own = String(custom || '').trim();
    if (own) return own;
    const first = Array.from(String(streamer || '').trim())[0] || '粉';
    return `${first}${FAN_MEDAL_SUFFIXES[stableHash(streamer) % FAN_MEDAL_SUFFIXES.length]}`;
}

