    let pkg = null, source = null, sourceName = '', modelId = '', remoteUrl = '', staged = false, busy = false, closed = false, dirty = false, generation = 0, replay = 0;
    let metadata = { expressions: [], motions: {} }, originalName = '', activeRow = null, restoredBackup = null;
    const preview = { snapshot: { content: {} } };
    const panel = doc.createElement('dialog'); panel.className = 'igs-live2d-panel';
    panel.innerHTML = `<style>${LIVE2D_EDITOR_STYLE}</style><form><header><div><h2>Live2D 角色工作台</h2><p>角色 / Live2D / 模型与差分 · <span data-scope></span></p></div><button type="button" data-close aria-label="关闭 Live2D 编辑器">✕</button></header><div class="igs-l2-workspace"><section class="igs-l2-left"><div class="igs-l2-heading"><h3>实时预览</h3><button type="button" data-background style="padding:4px 9px;font-size:12px">切换底色</button></div><div class="igs-l2-preview" data-preview><div data-sprite></div><div class="igs-l2-empty"><b>◇</b><strong>让角色动起来</strong><span>导入模型后在这里预览<br>右侧绑定差分，点击 ▶ 试播</span></div></div><div class="igs-l2-status" role="status" aria-live="polite" data-status>等待导入模型</div><div class="igs-l2-import" data-drop><div class="igs-l2-buttons"><button class="primary" type="button" data-import>导入模型 / 成品 ZIP</button><button type="button" data-folder>选择文件夹</button></div><input type="file" accept=".zip,application/zip" data-zip-input hidden><input type="file" webkitdirectory multiple data-folder-input hidden></div><label class="igs-l2-field" data-entry-field hidden><span>模型包包含多个入口，请选择</span><select data-entry></select></label><div class="igs-l2-model" data-model>支持 Cubism 2 / 3 / 4 模型。文件保存在当前浏览器，不上传至第三方。</div><small>模型资源可本地读取；首次加载运行库仍需联网。请确认模型与 SDK 的使用授权。</small></section><section class="igs-l2-right"><section><div class="igs-l2-heading"><h3>01　角色与模型</h3><span class="igs-l2-tag">启用后暂停该角色静态差分</span></div><div class="igs-l2-row"><label class="igs-l2-field"><span>绑定角色名</span><input data-name list="igs-live2d-character-names" placeholder="与剧情中的角色名一致" required><datalist id="igs-live2d-character-names"></datalist></label><label class="igs-l2-field"><span>编辑已保存角色</span><select data-list><option value="">新建绑定</option></select></label></div></section><section><div class="igs-l2-heading"><h3>02　差分 → 表情 / 动作</h3><button type="button" data-add style="font-size:12px;padding:5px 9px">＋ 添加差分</button></div><div class="igs-l2-map labels"><span>差分名称</span><span>模型表情</span><span>动作 / 序号</span><span>试播</span><span></span></div><div class="igs-l2-maps" data-maps></div></section><section><div class="igs-l2-heading"><h3>03　舞台位置</h3><button type="button" data-reset-layout style="font-size:12px;padding:5px 9px">重置</button></div><div class="igs-l2-layout">${[['scale','高度',1,250,90],['posX','横向',-100,200,50],['posY','纵向',-100,200,100]].map(([key,label,min,max,value]) => `<label class="igs-l2-field"><span>${label}<output data-output="${key}">${value}%</output></span><input data-${key} type="range" min="${min}" max="${max}" value="${value}"></label>`).join('')}</div></section><details><summary>高级：远程模型与运行库</summary><label>模型清单 URL<input data-url type="url" placeholder="https://…/model3.json"></label><button type="button" data-remote>加载远程模型</button><label>Cubism 2 Core<input data-core2 type="url"></label><label>Cubism 3/4 Core<input data-core4 type="url"></label></details></section></div><footer><p class="igs-l2-error" role="alert" data-error></p><div class="igs-l2-footer-actions"><label class="igs-l2-enable"><input type="checkbox" data-enabled>本卡启用 Live2D</label><div class="igs-l2-buttons"><button type="button" data-export>导出成品包</button><button class="danger" type="button" data-disable>移除绑定</button><button class="primary" type="submit" data-save>保存并应用</button></div></div><small>保存在本浏览器；保存不会上传模型。成品包包含模型与差分绑定，可直接导入；原“本卡素材包”暂不包含 Live2D。</small></footer></form>`;
    const q = name => panel.querySelector('[data-' + name + ']');
    q('scope').textContent = options.scopeLabel || (scope ? '当前角色卡' : '未选卡范围');
    q('enabled').checked = config.enabled; q('core2').value = config.runtime.core2; q('core4').value = config.runtime.core4;
    const characters = options.characters || {};
