            const { name, binding, runtime: nextRuntime } = collect();
            const next = readLive2dConfig(storage, scope);
            if (name !== originalName && next.bindings[name] && !win.confirm('角色「' + name + '」已有模型绑定，确定替换？')) return;
            setBusy(true);
