        q('status').textContent = status.type === 'ready' ? '● 模型已就绪 · 点击右侧 ▶ 试播差分' + (status.warning ? '\n' + status.warning : '') : status.message || '正在加载运行库…';
        const version = JSON.stringify([status.expressions, status.motions]);
