function classifyLiveTopic(text) {
    const body = clean(text);
    if (!body) return null;
    let best = null;
    let bestScore = 0;
    for (const [name, re, lines] of LIVE_TOPIC_BUCKETS) {
        const score = (body.match(new RegExp(re.source, 'g')) || []).length;
        if (score > bestScore) {
            best = { name, lines };
            bestScore = score;
        }
    }
    return best;
}
