const IMAGE_FAILURE_KINDS = Object.freeze(['timeout', 'network', 'server5xx', 'rateLimit429', 'emptyOrBroken', 'moderation', 'authOrParam', 'pluginTimeout', 'unknown']);

const MODERATION = /审核|违规|违禁|敏感内容|内容安全|moderation|safety|nsfw filter|content policy|blocked|censor/i;
