const { normalizeBgmSettings } = require("src/visual/igs-ui/scene-audio.js");
// 「声音 › 背景音乐」的曲目操作：下载 / 移除默认曲目、上传本地音频、添加直链、编辑、删除。
const BGM_ACTION_RE = /^bgm-(?:track-(?:add|upload|edit|remove)|pack-(?:download|remove))(?::.*)?$/;

