    if (status === 'no-api') return `<div class="igs-shujuku-empty">未检测到 shujuku 数据库插件</div>`;
    if (status === 'error') return `<div class="igs-shujuku-empty">加载失败：${e(errorMsg || '未知错误')}</div>`;
