        if (beachBand && nearestOnPolyline(x, y, scene.sea.coast).distance < beachBand) { grid.zone[i] = Z_SAND; continue; }
        const disc = discs.find(d => dist(x, y, d.x, d.y) < d.r * (1 + 0.22 * noise(Math.atan2(y - d.y, x - d.x) * 1.2 + d.phase, 3.1)));
