        const graphNodes = [{ person: chosen, x: 50, y: neighbors.length ? 24 : 50 }, ...neighbors.map((person, index) =>
            ({ person, x: neighborX[index], y: neighbors.length > 4 && index % 2 ? 80 : 72 }))].filter(item => item.person);
