    generate: (args) => (args[2] && args[2].imageKind) || 'cg',
    generateCaption: (args) => (args[0] && args[0].imageKind) || 'cg',
    generateDbgenCaption: (args) => (args[0] && args[0].imageKind) || 'cg',
